"use client";

// Artwork, label and open mark form one centred column; the label used to sit at the start under centred artwork with
// the mark floating at the row end (2026-10-17 review E20).
// Fixed 260×160 artwork is decorative; cap at three previews to keep the motif bounded. The trigger label and expanded content remain fluid.
import type{ReactNode}from'react';import{Collapsible,CollapsibleMarker}from'./collapsible.js';import{useHjmTheme}from'./provider.js';
import type { HjmCompositionStyleProp } from "./composition-style.js";
export type FolderPreviewProps=Readonly<{label:string;open:boolean;onOpenChange:(open:boolean)=>void;previews:readonly ReactNode[];children:ReactNode;disabled?:boolean;
 /** Canonical layout-only placement on the root Collapsible. Controlled visual keys are excluded. */
 layoutStyle?:HjmCompositionStyleProp}>;
/** Preview slots are decorative snapshots; expanded children own real actions and accessible content. */
export function FolderPreview({label,open,onOpenChange,previews,children,disabled=false,layoutStyle}:FolderPreviewProps){const{environment}=useHjmTheme();if(!label.trim())throw new TypeError('Folder needs a label');return <Collapsible open={open} onOpenChange={onOpenChange} disabled={disabled} {...(layoutStyle===undefined?{}:{layoutStyle})} marker="none" trigger={<div style={{width:'100%',minWidth:0,display:'flex',flexDirection:'column',alignItems:'center',gap:'var(--hjm-space-sm)'}}><div inert aria-hidden="true" style={{position:'relative',height:160,width:'100%',maxWidth:260,pointerEvents:'none'}}>{previews.slice(0,3).map((preview,index)=><div key={index} style={{position:'absolute',insetInlineStart:'20%',top:24+index*8,width:'60%',height:104,overflow:'hidden',borderRadius:'var(--hjm-radius-md)',background:'var(--hjm-color-surface-alt)',border:'1px solid var(--hjm-color-border)',transform:`translateX(${(index-1)*(open?34:10)}px) rotate(${(index-1)*(open?12:4)}deg)`,transition:environment.reducedMotion?'none':'transform 200ms ease-out'}}>{preview}</div>)}<div style={{position:'absolute',bottom:0,insetInline:0,height:56,borderRadius:'var(--hjm-radius-lg)',background:'var(--hjm-color-surface-accent)',border:'1px solid var(--hjm-color-border)',transformOrigin:'bottom',transform:open?'perspective(400px) rotateX(-15deg)':'none'}}/></div><span style={{display:'inline-flex',alignItems:'center',gap:'var(--hjm-space-xs)',textAlign:'center'}}><span>{label}</span><CollapsibleMarker open={open}/></span></div>}>{children}</Collapsible>;}
